import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: menu.name 이 검색 카테고리 이름(전자결재·게시판·일정·문서함)과 같다.
// 가정: 게시판 첨부파일의 attachment.target_type 은 'BOARD_POST', 결재문서 첨부는 'APPROVAL_DOCUMENT'.
const CATEGORIES = ['전자결재', '게시판', '일정', '문서함'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

// 조회자의 메뉴 사용 권한(조회 범위: 전체/부서/개인) 안의 결과만 모은다.
const HITS_SQL = `
  WITH me AS (
    SELECT employee_id, department_id
    FROM employee
    WHERE employee_id = CAST(:userId AS bigint)
  ),
  perm AS (
    SELECT m.name AS menu_name, p.view_scope AS view_scope
    FROM menu_permission p
    JOIN menu m ON m.menu_id = p.menu_id
    WHERE p.employee_id = CAST(:userId AS bigint)
      AND m.use_status = '사용'
  ),
  hits AS (
    SELECT '전자결재' AS category, d.approval_document_id AS target_id, d.title AS title,
           CAST(NULL AS bigint) AS attachment_id, CAST(NULL AS varchar) AS file_name
    FROM approval_document d
    JOIN employee e ON e.employee_id = d.drafter_id
    JOIN perm ON perm.menu_name = '전자결재'
    CROSS JOIN me
    WHERE (d.title ILIKE :kw OR d.body ILIKE :kw)
      AND (perm.view_scope = '전체'
        OR (perm.view_scope = '부서' AND e.department_id = me.department_id)
        OR (perm.view_scope = '개인' AND d.drafter_id = me.employee_id))
    UNION ALL
    SELECT '전자결재', d.approval_document_id, d.title, a.attachment_id, a.file_name
    FROM attachment a
    JOIN approval_document d ON d.approval_document_id = a.target_id
    JOIN employee e ON e.employee_id = d.drafter_id
    JOIN perm ON perm.menu_name = '전자결재'
    CROSS JOIN me
    WHERE a.target_type = 'APPROVAL_DOCUMENT'
      AND a.file_name ILIKE :kw
      AND (perm.view_scope = '전체'
        OR (perm.view_scope = '부서' AND e.department_id = me.department_id)
        OR (perm.view_scope = '개인' AND d.drafter_id = me.employee_id))
    UNION ALL
    SELECT '게시판', b.board_post_id, b.title, CAST(NULL AS bigint), CAST(NULL AS varchar)
    FROM board_post b
    JOIN employee e ON e.employee_id = b.author_id
    JOIN perm ON perm.menu_name = '게시판'
    CROSS JOIN me
    WHERE (b.title ILIKE :kw OR b.content ILIKE :kw)
      AND (perm.view_scope = '전체'
        OR (perm.view_scope = '부서' AND e.department_id = me.department_id)
        OR (perm.view_scope = '개인' AND b.author_id = me.employee_id))
    UNION ALL
    SELECT '게시판', b.board_post_id, b.title, a.attachment_id, a.file_name
    FROM attachment a
    JOIN board_post b ON b.board_post_id = a.target_id
    JOIN employee e ON e.employee_id = b.author_id
    JOIN perm ON perm.menu_name = '게시판'
    CROSS JOIN me
    WHERE a.target_type = 'BOARD_POST'
      AND a.file_name ILIKE :kw
      AND (perm.view_scope = '전체'
        OR (perm.view_scope = '부서' AND e.department_id = me.department_id)
        OR (perm.view_scope = '개인' AND b.author_id = me.employee_id))
    UNION ALL
    SELECT '일정', s.schedule_id, s.title, CAST(NULL AS bigint), CAST(NULL AS varchar)
    FROM schedule s
    JOIN employee e ON e.employee_id = s.owner_id
    JOIN perm ON perm.menu_name = '일정'
    CROSS JOIN me
    WHERE (s.title ILIKE :kw OR s.content ILIKE :kw OR s.location ILIKE :kw)
      AND (perm.view_scope = '전체'
        OR (perm.view_scope = '부서' AND e.department_id = me.department_id)
        OR (perm.view_scope = '개인' AND s.owner_id = me.employee_id))
    UNION ALL
    SELECT '문서함', x.document_box_id, x.name, CAST(NULL AS bigint), CAST(NULL AS varchar)
    FROM document_box x
    LEFT JOIN employee e ON e.employee_id = x.employee_id
    JOIN perm ON perm.menu_name = '문서함'
    CROSS JOIN me
    WHERE x.name ILIKE :kw
      AND (perm.view_scope = '전체'
        OR (perm.view_scope = '부서' AND COALESCE(x.department_id, e.department_id) = me.department_id)
        OR (perm.view_scope = '개인' AND x.employee_id = me.employee_id))
  )
`;

@Controller('api/v1')
export class FnSfr03901Controller {
  @Get('/integrated-searches')
  async searchIntegrated(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.queryOf(req.query);
    const rawKeyword = data['keyword'];
    const keyword = typeof rawKeyword === 'string' ? rawKeyword.trim() : '';
    if (keyword === '') {
      throw new ApiError(422, 'SEARCH_KEYWORD_REQUIRED', '검색어를 입력해 주세요.');
    }
    const rawCategory = data['category'];
    let category: string | null = null;
    if (rawCategory !== undefined && rawCategory !== null && rawCategory !== '') {
      if (typeof rawCategory !== 'string' || !CATEGORIES.includes(rawCategory)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '검색 카테고리가 올바르지 않습니다.');
      }
      category = rawCategory;
    }
    const rawPage = data['page'] === undefined || data['page'] === '' ? 0 : Number(data['page']);
    const rawSize = data['size'] === undefined || data['size'] === '' ? DEFAULT_SIZE : Number(data['size']);
    if (!Number.isInteger(rawPage) || rawPage < 0 || !Number.isInteger(rawSize) || rawSize < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기가 올바르지 않습니다.');
    }
    const page = rawPage;
    const size = Math.min(rawSize, MAX_SIZE);
    const kw = '%' + keyword.replace(/[\\%_]/g, (m) => '\\' + m) + '%';
    return transaction(async (db) => {
      const params = {
        userId: user.id,
        kw: kw,
        category: category,
        size: size,
        offset: page * size,
      };
      const items = await db.query(
        HITS_SQL + `
        SELECT category AS "category",
               CAST(COUNT(*) OVER (PARTITION BY category) AS integer) AS "categoryCount",
               target_id AS "targetId",
               title AS "title",
               attachment_id AS "attachmentId",
               file_name AS "fileName"
        FROM hits
        WHERE CAST(:category AS varchar) IS NULL OR category = CAST(:category AS varchar)
        ORDER BY category, target_id DESC, attachment_id NULLS FIRST
        LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        params,
      );
      const totals = await db.query(
        HITS_SQL + `
        SELECT CAST(COUNT(*) AS integer) AS "total"
        FROM hits
        WHERE CAST(:category AS varchar) IS NULL OR category = CAST(:category AS varchar)`,
        params,
      );
      const total = totals.length > 0 ? Number(totals[0]['total']) : 0;
      return { items: items, page: page, size: size, total: total };
    });
  }
}

