import { useState } from 'react';
import { call, useData, Filters, Band, DataTable, Pager, Tiles, Field, TextInput, Select, ErrorText, Num, Badge } from '../kit';
import type { PageProps, Page, Row } from '../kit';

const CATEGORIES = ['전자결재', '게시판', '일정', '문서함'];

interface Applied {
  keyword: string;
  category: string;
  page: number;
}

export default function FnSfr03901Page({ role, notify }: PageProps) {
  const [keyword, setKeyword] = useState('');
  const [category, setCategory] = useState('');
  const [applied, setApplied] = useState<Applied | null>(null);

  const { data, error, loading } = useData(async () => {
    if (!applied) {
      return null;
    }
    const list = await call<Page>('GET', '/integrated-searches', role, undefined, {
      keyword: applied.keyword,
      category: applied.category,
      page: applied.page,
      size: 20,
    });
    const counts: [string, number][] = [];
    for (const c of CATEGORIES) {
      const r = await call<Page>('GET', '/integrated-searches', role, undefined, {
        keyword: applied.keyword,
        category: c,
        page: 0,
        size: 1,
      });
      const first = r.items[0];
      counts.push([c, first ? Number(first['categoryCount']) : 0]);
    }
    return { list, counts };
  }, [role, applied]);

  function search() {
    if (keyword.trim() === '') {
      notify('검색어를 입력해 주세요.');
      return;
    }
    setApplied({ keyword: keyword.trim(), category, page: 0 });
  }

  function reset() {
    setKeyword('');
    setCategory('');
    setApplied(null);
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>통합검색</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="검색어" required>
            <TextInput value={keyword} onChange={setKeyword} placeholder="검색어를 입력해 주세요." />
          </Field>
          <Field label="검색 카테고리">
            <Select
              value={category}
              onChange={setCategory}
              options={CATEGORIES.map((c): [string, string] => [c, c])}
              placeholder="전체"
            />
          </Field>
        </Filters>
      </section>
      <section className="box">
        <h2>검색 결과</h2>
        {error ? <ErrorText text={error} /> : null}
        {!applied ? <p>검색어를 입력하고 조회해 주세요.</p> : null}
        {applied && loading && !data ? <p>검색하고 있습니다.</p> : null}
        {data ? (
          <>
            <Tiles items={data.counts.map(([c, n]): [string, React.ReactNode] => [c, <Num value={n} />])} />
            <Band total={data.list.total} />
            <DataTable<Row>
              columns={[
                { key: 'category', label: '결과 카테고리', render: (r) => <Badge value={r['category']} /> },
                { key: 'title', label: '제목' },
                { key: 'fileName', label: '파일명' },
              ]}
              rows={data.list.items}
              empty="검색 결과가 없습니다. 다른 검색어로 다시 조회해 보세요."
            />
            <Pager
              page={data.list.page}
              size={data.list.size}
              total={data.list.total}
              onPage={(p) => applied && setApplied({ ...applied, page: p })}
            />
          </>
        ) : null}
      </section>
    </div>
  );
}
